    const id = Math.ceil(Math.random() * 1000);
	return {
        items: [{
            "id": `alert123${id}`,
            "status": "positive",
            "icon": "circle-info-outline",
            "content": event.payload.data.output.message,
            "action": {
                "type": "dismiss"
            }
        }]
    };
}

